function circuit(){return `<svg class="mini-circuit" viewBox="0 0 260 115" role="img" aria-label="A voltage source, resistor and capacitor in series"><g fill="none" stroke="currentColor" stroke-width="1.5" style="color:#668773"><path d="M40 43V24h50l5-6 7 12 7-12 7 12 7-12 7 12 5-6h63v33M198 68v27H40V70"/><circle cx="40" cy="56" r="14"/><path d="M35 52h10M40 47v10M36 61h8M184 58h28M184 67h28"/></g><text x="107" y="10">R</text><text x="219" y="66">C</text><text x="10" y="60">Vₛ</text><text x="110" y="86">V꜀(t)</text><circle cx="198" cy="40" r="2.5" fill="#668773"/></svg>`}
function filtered(){let list=problems.filter(p=>(category==='All'||p.category===category)&&(difficulty==='All levels'||p.difficulty===difficulty)&&(`${p.title} ${p.tags.join(' ')} ${p.category} ${p.id}`.toLowerCase().includes(query.toLowerCase()))&&(view!=='saved'||saved.bookmarks.includes(p.id))&&(status==='all'||(status==='solved'?solved(p):!solved(p))));if(sort==='recommended')list=practice.recommended(list);if(sort==='difficulty')list.sort((a,b)=>['Easy','Medium','Hard'].indexOf(a.difficulty)-['Easy','Medium','Hard'].indexOf(b.difficulty));if(sort==='quick')list.sort((a,b)=>a.minutes-b.minutes);return list}
function tableRows(){const list=filtered();return list.length?`<div class="table-wrap"><table class="problem-table"><thead><tr><th aria-label="Status"></th><th>PROBLEM</th><th>DIFFICULTY</th><th>TIME</th><th aria-label="Save"></th></tr></thead><tbody>${list.map(p=>`<tr class="problem-row"><td><span class="status-circle ${solved(p)?'solved':''}" aria-label="${solved(p)?'Solved':'Unsolved'}">${solved(p)?icon('check',11):''}</span></td><td><button class="problem-title" data-problem="${p.id}"><span class="number">${String(p.id).padStart(2,'0')}.</span>${esc(p.title)}</button><div class="problem-tags">${p.tags.map(esc).join(' · ')}${diagramForProblem(p)?' · Diagram':''}</div></td><td>${difficultyBadge(p)}</td><td><span class="muted tiny">${p.minutes} min</span></td><td><button class="bookmark ${saved.bookmarks.includes(p.id)?'saved':''}" data-bookmark="${p.id}" aria-label="${saved.bookmarks.includes(p.id)?'Unsave':'Save'} ${esc(p.title)}" aria-pressed="${saved.bookmarks.includes(p.id)}">${icon('book',15)}</button></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${list.length} ${list.length===1?'problem':'problems'} to sharpen your thinking</span><span>Made for curious minds.</span></div>`:`<div class="empty"><h3>${view==='saved'?'Keep a good problem close.':'No matching problems'}</h3><p class="small">${view==='saved'?'Bookmark a problem to come back to it here.':'Try another topic or clear your filters.'}</p><button class="button" data-action="clear">Browse all problems</button></div>`}
function libraryPage(){const n=problems.filter(solved).length,total=problems.length;shell(`<div class="page"><div class="page-heading"><div><h1>${view==='saved'?'Worth another look.':'Your next breakthrough.'}</h1><p>${view==='saved'?'Your saved problems, ready when you are.':'Build your intuition. Work through a problem. Make it click.'}</p></div><div class="button-row"><button class="button" data-action="suggest">Suggest a problem</button><button class="button" data-action="random">${icon('shuffle',17)}Pick for me</button></div></div>${practice.libraryCard()}${interview.summaryCard()}<div class="category-grid">${categories.map(c=>`<button class="category-card ${category===c.name?'selected':''}" data-category="${c.name}" style="--topic:${c.color};--tint:${c.tint}" aria-pressed="${category===c.name}"><span class="category-icon">${icon(c.icon,21)}</span><span class="category-name">${c.name}</span><span class="category-count">${problems.filter(p=>p.category===c.name).length} problems</span></button>`).join('')}</div><div class="content-grid"><section class="library" aria-label="Problem library"><div class="library-heading"><h2>${category==='All'?(view==='saved'?'Saved problems':'Problem library'):category}</h2><span class="pill-count" id="result-count">${filtered().length}</span>${category!=='All'?'<button class="button link tiny" data-action="clear">Clear filter</button>':''}</div><div class="library-tools"><label class="search">${icon('search',16)}<input id="search" type="search" placeholder="Search problems or topics..." aria-label="Search problems" value="${esc(query)}"><span class="kbd">/</span></label><select class="select" id="difficulty" aria-label="Filter by difficulty">${['All levels','Easy','Medium','Hard'].map(x=>`<option ${x===difficulty?'selected':''}>${x}</option>`).join('')}</select><select class="select" id="sort" aria-label="Sort problems"><option value="recommended">Recommended</option><option value="difficulty" ${sort==='difficulty'?'selected':''}>Difficulty</option><option value="quick" ${sort==='quick'?'selected':''}>Quickest first</option></select></div><div class="filter-tabs" role="tablist" aria-label="Problem status">${[['all','All problems'],['unsolved','To do'],['solved','Solved']].map(([s,l])=>`<button class="filter-tab ${status===s?'active':''}" data-status="${s}" role="tab" aria-selected="${status===s}">${l}</button>`).join('')}</div><div id="table-content">${tableRows()}</div></section><aside class="right-rail">${practice.dailyCard()}<section class="rail-card"><div class="rail-heading"><h3>Your progress</h3>${icon('chart',17)}</div><div class="progress-summary"><div class="progress-ring" style="--pct:${n/total*100}%"><div class="ring-center"><strong>${n}<span style="font-size:12px;color:var(--muted);font-weight:400">/${total}</span></strong><small>SOLVED</small></div></div><div><strong>${n?'Keep it going.':'A fresh start.'}</strong><p>${n?'One concept at a time.':'Your first solve awaits.'}</p></div></div><div class="mini-bars">${['Easy','Medium','Hard'].map(d=>{const all=problems.filter(p=>p.difficulty===d),count=all.filter(solved).length;return `<div class="mini-bar"><span>${d}</span><div class="bar-track"><div class="bar-fill" style="width:${all.length?count/all.length*100:0}%"></div></div><span class="mono">${count}/${all.length}</span></div>`}).join('')}</div><div class="rail-footer">Consistency builds confidence.</div></section><section class="lab-callout">${icon('capacitor',24)}<div><h3>What happens if you change R?</h3><p>Turn the knobs. Watch the response. Connect the dots.</p><button data-view="lab">Explore the circuit lab</button></div></section></aside></div><div class="bottom-note">${icon('check',13)}${session.signedIn?'Your progress follows your account across devices.':HOSTING.externalFrontend?'Guest progress stays in this browser on this website.':'Guest progress is saved in this browser. Sign in to sync across devices.'}</div></div>`)}
