function problemPage(){const p=activeProblem;let description=`<span class="eyebrow muted">PROBLEM ${String(p.id).padStart(2,'0')} / ${p.category}</span><h1>${esc(p.title)}</h1><div class="problem-meta">${difficultyBadge(p)}<span class="small muted" style="display:flex;align-items:center;gap:5px">${icon('clock',14)}${p.minutes} min</span>${solved(p)?'<span class="small" style="color:var(--green)">✓ Solved</span>':''}</div>`;if(tab==='description')description+=`<p>${esc(p.prompt)}</p>${problemDiagram(p)}<div class="given-grid">${p.given.map(g=>`<div class="given"><small>${esc(g.label)}</small><strong>${esc(g.value)}</strong></div>`).join('')}</div><div class="task-box">${esc(p.task)}</div><div class="problem-lab-link"><p>Explore this topic with adjustable components. Lab values are separate from this question.</p><button class="button" data-sim-open="topic">${icon('bolt',15)}Open interactive lab</button></div>`;if(tab==='hints')description+=`<p>A nudge in the right direction. Open one hint at a time.</p>${(p.hints||[]).map((h,i)=>`<details class="hint-item"><summary>Hint ${i+1}</summary><p>${esc(h)}</p></details>`).join('')}`;if(tab==='solution')description+=walkthrough.markup(p);
description+=learning.referenceCard(p);
let answer='';const draft=saved.drafts[p.id]||'';if(p.type==='multipart'){let parts={};try{parts=JSON.parse(draft)||{};}catch{}answer=`<div class="multipart-fields">${p.parts.map(part=>`<label class="answer-label" for="answer-${esc(part.id)}">${esc(part.label)}</label><div class="answer-input"><input id="answer-${esc(part.id)}" data-answer-part="${esc(part.id)}" maxlength="200" autocomplete="off" placeholder="Value, units, or expression" value="${esc(parts[part.id]||'')}"><span>${esc(part.unit)}</span></div>`).join('')}</div><p class="hint-text">Each part earns feedback. All parts must pass to mark this problem solved. Include units or use the units shown.</p>`;}if(p.type==='numeric')answer=`<label class="answer-label" for="answer">Your answer</label><div class="answer-input"><input id="answer" maxlength="2500" name="answer" type="text" inputmode="decimal" autocomplete="off" placeholder="Enter a value" value="${esc(draft)}"><span>${esc(p.unit)}</span></div><p class="hint-text">Use ${esc(p.unit)}, equivalent units, or an expression. Accepted tolerance: ±${p.tolerance} ${esc(p.unit)}.</p>`;if(p.type==='choice')answer=`<div class="answer-label">Choose your answer</div>${p.options.map((o,i)=>`<label class="choice"><input type="radio" name="choice" value="${i}" ${draft===String(i)?'checked':''}><span>${esc(o)}</span></label>`).join('')}<div style="height:12px"></div>`;if(p.type==='hdl')answer=`<label class="answer-label" for="hdl">Verilog · continuous assignment</label><textarea id="hdl" maxlength="2500" class="code-editor" spellcheck="false" autocomplete="off" aria-label="Verilog code editor">${esc(draft||'assign y = 0;')}</textarea><p class="code-description">One-bit, 0/1 truth-table checker. Supports ~ ! & ^ | && || == != and ?: . No module declarations, timing, or X/Z simulation.</p>`;
shell(`<div id="practice-context">${practice.contextBanner(p)}</div><div class="workspace-header"><button class="button" data-action="back">${icon('grid',15)}Problem library</button><span class="small muted">Make the reasoning your own.</span><div style="display:flex;gap:8px"><button class="icon-button" data-action="previous" aria-label="Previous problem" ${problems.indexOf(p)===0?'disabled':''}>${icon('left',18)}</button><span class="small muted" style="align-self:center">${problems.indexOf(p)+1} / ${problems.length}</span><button class="icon-button" data-action="next" aria-label="Next problem" ${problems.indexOf(p)===problems.length-1?'disabled':''}>${icon('chevron',18)}</button><button class="icon-button bookmark ${saved.bookmarks.includes(p.id)?'saved':''}" data-bookmark="${p.id}" aria-label="${saved.bookmarks.includes(p.id)?'Unsave':'Save'} problem">${icon('book',18)}</button></div></div><div class="workspace-layout"><section class="problem-panel"><div class="panel-tabs" role="tablist" aria-label="Problem information">${[['description','Description'],['hints','Hints'],['solution','Solution']].map(([id,l])=>`<button class="filter-tab ${tab===id?'active':''}" role="tab" aria-selected="${tab===id}" data-tab="${id}">${l}</button>`).join('')}</div><div class="problem-content">${description}<div class="problem-report-link"><span class="small muted">Something could be clearer?</span><button class="button link small" data-action="report">Report an issue</button></div></div></section><section class="work-panel"><form class="work-card" id="answer-form"><div class="work-card-head"><h3>${p.type==='hdl'?'Code workbench':'Your workbench'}</h3><span class="tiny muted">${p.type==='hdl'?'Combinational logic':'Think · solve · check'}</span></div><div class="work-body">${answer}<div class="button-row"><button class="button" type="button" data-action="${p.type==='hdl'?'run':'hint'}">${icon(p.type==='hdl'?'play':'bulb',15)}${p.type==='hdl'?'Run tests':'Need a hint?'}</button><button class="button primary" type="submit">${icon('check',16)}Submit answer</button></div><div id="feedback">${resultHTML()}</div></div></form><section class="work-card"><div class="work-card-head"><h3>Scratchpad</h3><span class="tiny muted">Just for you</span></div><textarea id="scratchpad" maxlength="10000" class="scratchpad" aria-label="Scratchpad" placeholder="Start with what you know.&#10;&#10;Write equations, sketch your reasoning...">${esc(saved.notes[p.id]||'')}</textarea><div class="scratch-footer" data-sync-status>${esc(practiceSyncText())}</div></section>${p.category==='RC circuits'?`<div class="lab-callout">${icon('capacitor',24)}<div><h3>See the transient in action.</h3><p>Explore charging and discharging with adjustable components.</p><button data-view="lab">Open the circuit lab</button></div></div>`:''}</section></div>`);}
function progressPage(){const attempts=session.signedIn?saved.attemptCount:saved.attempts.length,correct=session.signedIn?saved.acceptedCount:saved.attempts.filter(a=>a.pass).length;const solvedIds=new Set(saved.solved);shell(`<div class="page"><div class="page-heading"><div><h1>Every solve adds up.</h1><p>Your practice, at a glance. ${session.signedIn?'Synced with your account.':'Saved in this browser.'}</p></div><button class="button primary" data-action="random">${icon('play',16)}Keep practicing</button></div><div class="progress-top"><div class="stat-card"><p>Problems solved</p><strong>${problems.filter(solved).length}<span class="muted" style="font-size:18px;font-weight:400"> / ${problems.length}</span></strong><p>Concepts put into practice</p></div><div class="stat-card"><p>Total submissions</p><strong>${attempts}</strong><p>Every attempt is a step forward</p></div><div class="stat-card"><p>Accepted submissions</p><strong>${attempts?Math.round(correct/attempts*100)+'%':'—'}</strong><p>${correct} accepted of ${attempts} submissions</p></div></div>${insights.summaryCard()}<div class="progress-topics">${categories.map(c=>{const list=problems.filter(p=>p.category===c.name),n=list.filter(p=>solvedIds.has(p.id)).length;return `<section class="topic-progress"><div class="rail-heading"><div style="display:flex;align-items:center;gap:12px;color:${c.color}">${icon(c.icon,22)}<h3 style="color:var(--text)">${c.name}</h3></div><span class="small mono muted">${n} / ${list.length}</span></div><div class="bar-track"><div class="bar-fill" style="width:${n/list.length*100}%;background:${c.color}"></div></div><div class="rail-heading"><p>${n===list.length?'Topic complete. Nicely done.':`${list.length-n} problems to explore`}</p><button class="button link small" data-category="${c.name}">Practice</button></div></section>`}).join('')}</div>${attempts?`<section class="rail-card" style="margin-top:25px"><h2 style="font-size:18px">Recent submissions</h2><table class="problem-table"><tbody>${saved.attempts.slice(-8).reverse().map(a=>{const p=problems.find(p=>p.id===a.id);return `<tr><td style="width:auto">${a.pass?'<span style="color:var(--green)">Accepted</span>':'Try again'}</td><td><button class="problem-title" data-problem="${a.id}">${esc(p?.title||'Problem')}</button><span class="tiny muted">${a.source==='imported'?'Imported browser history · ':''}${esc(assistanceLabel(a.assistance))}</span></td><td class="muted tiny">${new Date(a.at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</td></tr>`}).join('')}</tbody></table></section>`:''}</div>`)}
const practice=createPractice({shell,icon,esc,getProblems:()=>problems,getProgress:()=>saved,openProblem,navigate});
const interview=createInterview({shell,esc,icon,getProblems:()=>problems,getProgress:()=>saved,storage:interviewStore,gradeAnswer:gradeInterviewAnswer,openProblem,navigate,diagramForProblem,isActive:()=>view==='interview'&&!activeProblem,toast});
interview.restore();
const walkthrough=createWalkthrough({esc,getProblem:()=>tab==='solution'?activeProblem:null});
const roleTracks=createRoleTracks({shell,esc,icon,getProblems:()=>problems,getProgress:()=>saved,openProblem,navigate,prepareInterview:id=>interview.startTrack(id)});
