const hdlWorkbench=createHDLWorkbench({shell,esc,icon,isActive:()=>view==='hdl'&&!activeProblem});
const insights=createInsights({shell,esc,icon,getProblems:()=>problems,getProgress:()=>saved,categories,openProblem,navigate,startInterview:topic=>interview.startFocused(topic)});
const admin=createAdmin({shell,icon,esc,api,getSession:()=>session,reloadLibrary:async()=>{problems=await api('/api/problems')},toast,isActive:()=>canManage()&&view==='admin'&&!activeProblem});
const feedback=createFeedback({shell,esc,api,handoffOrigin:HOSTING.externalFrontend?HOSTING.apiOrigin:null,getSession:()=>session,toast,isActive:()=>canManage()&&view==='reports'&&!activeProblem,editProblem:async id=>{if(navigate('admin'))await admin.editProblem(id)}});
const simulations=createSimulations({shell,icon,esc,isActive:()=>view==='lab'&&!activeProblem,getProblems:()=>problems,openProblem});
const account=createAccount({externalFrontend:HOSTING.externalFrontend,accountError,shell,esc,icon,getSession:()=>session,getStore:()=>learner,getGuest:()=>guest,getGuestPending:()=>guestStore.hasPending,auth,api,beforeAuth:async({reauth=false}={})=>{guest=guestStore.flush();await learner.flush();await interviewStore.flush();await Promise.all(labStores.map(store=>store.flush()));if(labStores.some(store=>store.hasPending&&!(reauth&&store.status.authLost))||guestStore.hasPending||(interviewStore.hasPending&&!(reauth&&interviewStore.status.authLost))||(learner.hasPending&&!(reauth&&learner.status.authLost)))throw new Error('Save or resolve pending progress changes before changing your sign-in.');},afterAuth:async()=>{if(learner.hasPending||interviewStore.hasPending||labStores.some(store=>store.hasPending)){const current=await api('/api/session');await learner.resumeAuth(current);await interviewStore.resumeAuth(current);await Promise.all(labStores.map(store=>store.resumeAuth(current)));interview.restore();debugging.restore();design.restore();session=current;render();return;}location.href=auth?.accountPath||(HOSTING.externalFrontend?'/ohm/#account':'/#account');location.reload();},problems:()=>problems,toast,render:()=>{if(view==='account'&&!activeProblem)render();}});
function unavailableWorkspacePage(){
 shell(`<div class="page"><section class="editor-access rail-card"><h1>This page isn’t available.</h1><p class="muted">Return to your practice workspace to keep learning.</p><button class="button primary" data-view="problems">Back to practice</button></section></div>`);
}
function render(){if(!activeProblem&&['admin','reports'].includes(view)){if(!canManage()){unavailableWorkspacePage();return;}if(view==='admin')admin.render();else feedback.render();return;}if(session.signedIn&&learner.status.authLost)interview.discard();if(libraryError){shell(`<div class="load-error"><h1>The library is taking a moment.</h1><p>${esc(libraryError)}</p><button class="button primary" data-action="reload">Try again</button></div>`);return;}if(view==='account'&&!activeProblem){account.page();return;}if(session.signedIn&&(!learner.status.ready||learner.status.authLost)){shell(`<div class="account-loading"><h1>${learner.status.authLost?'Your sign-in changed.':'Your progress is taking a moment.'}</h1><p>${esc(learner.status.error||'Loading your account progress…')}</p><button class="button primary" data-view="account">Open account</button></div>`);return;}if(view==='reports'&&!activeProblem){feedback.render();return;}if(view==='admin'&&!activeProblem){admin.render();return;}if(!problems.length&&!activeProblem&&view!=='lab'){shell(`<div class="page"><h1>The collection is getting ready.</h1><p class="muted" style="margin-top:15px">Published problems will appear here.</p>${canManage()?'<button class="button" data-view="admin" style="margin-top:20px">Problem editor</button>':''}</div>`);return;}if(activeProblem)problemPage();else if(['roadmap','review'].includes(view))practice.render(view);else if(view==='interview')interview.render();else if(view==='insights')insights.render();else if(view==='lab')simulations.render();else if(view==='learn')learning.render();else if(view==='hdl')hdlWorkbench.render();else if(view==='roles')roleTracks.render();else if(view==='debug')debugging.render();else if(view==='design')design.render();else if(view==='help')helpPage({shell,esc});else if(view==='progress')progressPage();else libraryPage()}
function openProblem(id){if(view==='admin'&&!admin.canLeave()||view==='reports'&&!feedback.canLeave())return false;const p=problems.find(p=>p.id===Number(id));if(!p)return false;simulations.stop();hdlWorkbench.stop();tabRequest++;view='problems';activeProblem=p;tab='description';result=null;menu=false;location.hash=`problem/${p.id}`;render();window.scrollTo(0,0);return true}
function navigate(v){if(!['problems','saved','progress','lab','admin','reports','account','roadmap','review','interview','insights','learn','hdl','help','roles','debug','design'].includes(v))return;if(view==='admin'&&!admin.canLeave()||view==='reports'&&!feedback.canLeave())return;simulations.stop();hdlWorkbench.stop();tabRequest++;activeProblem=null;view=v;menu=false;location.hash=v;render();window.scrollTo(0,0);return true}
async function gradeInterviewAnswer(problem,answer){
 const accountId=session.signedIn?session.user?.id:null;
 const checked=session.signedIn
  ?await learner.submit({problemId:problem.id,version:problem.version,answer})
  :await api(`/api/problems/${problem.id}/check`,{method:'POST',body:JSON.stringify({answer,version:problem.version})});
 // Never reveal a response in a workspace whose account changed in flight.
 if(session.signedIn&&(learner.status.authLost||session.user?.id!==accountId))throw new Error('Your sign-in changed. Reload before continuing.');
 if(typeof checked.pass!=='boolean')throw new Error('The answer could not be checked. Please retry.');
 if(!session.signedIn){
  guest=guestStore.record({id:problem.id,pass:checked.pass,at:new Date().toISOString()});
  saved={...guest,theme:saved.theme};
  if(guestStore.hasPending)toast('Answer checked. Browser storage is unavailable; keep this tab open and retry saving.');
 }
 updateSyncStatus();
 return checked;
}
function readAnswer(){const p=activeProblem;return p.type==='multipart'?JSON.stringify(Object.fromEntries([...document.querySelectorAll('[data-answer-part]')].map(el=>[el.dataset.answerPart,el.value]))):p.type==='numeric'?document.querySelector('#answer').value:p.type==='hdl'?document.querySelector('#hdl').value:(document.querySelector('input[name=choice]:checked')?.value??'')}
let submitting=false,tabRequest=0;
async function submit(runOnly=false){if(submitting)return;const p=activeProblem,value=readAnswer(),problemId=p.id,problemVersion=p.version;if(!setPracticeField('draft',p.id,value))return;submitting=true;const buttons=[...document.querySelectorAll('#answer-form button')];buttons.forEach(b=>b.disabled=true);try{const answer=p.type==='choice'?(p.options[Number(value)]??''):value;if(p.type==='choice'&&value==='')throw new Error('Choose an answer before submitting.');const checked=session.signedIn&&!runOnly?await learner.submit({problemId:p.id,version:p.version,answer}):await api(`/api/problems/${p.id}/check`,{method:'POST',body:JSON.stringify({answer,version:p.version})});const pass=checked.pass;const nextResult={...checked,title:pass?(runOnly?'All tests passed':'Accepted. Nicely reasoned.'):(runOnly?'Some tests failed':'Not quite. Give it another try.'),message:checked.feedback|| (pass?(runOnly?'Your logic matches every input combination. Submit to save this solve.':'Your answer checks out. Open the solution to compare the reasoning.'):(p.type==='hdl'?'Compare the failing inputs with the expected output.':'Check your units, signs, and assumptions. A hint can help you find the next step.'))};if(!runOnly&&!session.signedIn){guest=guestStore.record({id:p.id,pass,at:new Date().toISOString(),assistance:guestAssistance[`${p.id}:${p.version}`]||'independent'});saved={...guest,theme:saved.theme};}persist();if(activeProblem?.id===problemId&&activeProblem?.version===problemVersion){result=nextResult;if(document.querySelector('#feedback'))document.querySelector('#feedback').innerHTML=resultHTML();const context=document.querySelector('#practice-context');if(context)context.innerHTML=practice.contextBanner(activeProblem);}updateSyncStatus();if(!runOnly&&!session.signedIn&&guestStore.hasPending)toast('Answer checked. Progress is only kept in this tab; retry saving before closing it.');else if(pass&&!runOnly)toast('Problem solved. Progress saved.');}catch(e){if(activeProblem?.id===problemId&&activeProblem?.version===problemVersion){result={pass:false,title:'Check your submission',message:e.message};if(document.querySelector('#feedback'))document.querySelector('#feedback').innerHTML=resultHTML();}}finally{submitting=false;buttons.forEach(b=>b.disabled=false)}}
async function selectTab(next){
 const p=activeProblem,request=++tabRequest;if(!p||!['description','hints','solution'].includes(next))return;
 try{
  if(next==='hints'&&!p.hints)Object.assign(p,await api(`/api/problems/${p.id}/hints?version=${p.version}`));
  if(next==='solution'&&!p.explanation)Object.assign(p,await api(`/api/problems/${p.id}/solution?version=${p.version}`));
  if(request===tabRequest&&activeProblem===p){
   if(next==='hints'||next==='solution'){const kind=next==='hints'?'hint':'solution';if(session.signedIn){await api('/api/account/assistance',{method:'POST',headers:{'X-Ohm-Account-ID':session.user.id,'X-CSRF-Token':session.csrfToken},body:JSON.stringify({problemId:p.id,version:p.version,kind})});}else{const key=`${p.id}:${p.version}`;guestAssistance[key]=guestAssistance[key]==='solution'?'solution':kind;try{localStorage.setItem('ohm-guest-assistance-v1',JSON.stringify(guestAssistance));}catch{}}}
   if(request===tabRequest&&activeProblem===p){tab=next;render();}
  }
 }catch(e){if(request===tabRequest&&activeProblem===p)toast(e.message);}
}

app.addEventListener('click',e=>{if(walkthrough.onClick(e)||roleTracks.onClick(e)||debugging.onClick(e)||design.onClick(e)||learning.onClick(e)||hdlWorkbench.onClick(e)||interview.onClick(e)||insights.onClick(e))return;if(practice.onClick(e))return;if(openDiagramViewer(e))return;if(simulations.onClick(e))return;if(e.target.closest('[data-account-action],[data-account-signout],[data-conflict],[data-auth-action]')){void account.onClick(e);return;}if(feedback.onClick(e)||admin.onClick(e))return;const b=e.target.closest('button');if(!b)return;if(b.dataset.view)return navigate(b.dataset.view);if(b.dataset.problem)return openProblem(b.dataset.problem);if(b.dataset.category){category=category===b.dataset.category?'All':b.dataset.category;status='all';query='';difficulty='All levels';return navigate('problems')}if(b.dataset.bookmark){const id=Number(b.dataset.bookmark);setPracticeField('bookmark',id,!saved.bookmarks.includes(id));render();return}if(b.dataset.status){status=b.dataset.status;return render()}if(b.dataset.tab)return selectTab(b.dataset.tab);if(b.dataset.simOpen){simulations.openFor(activeProblem);return navigate('lab')}switch(b.dataset.action){case 'retry-guest':guest=guestStore.flush();saved={...guest,theme:saved.theme};render();break;case 'suggest':feedback.open();break;case 'report':feedback.open(activeProblem);break;case 'theme':if(admin.isBusy()||feedback.isBusy()){toast('Please wait until this save finishes.');break;}admin.capture();feedback.capture();saved.theme=saved.theme==='dark'?'light':'dark';persist();render();break;case 'menu':menu=!menu;document.querySelector('.sidebar').classList.toggle('open',menu);document.querySelector('.sidebar').inert=!menu&&window.matchMedia('(max-width:700px)').matches;if(menu)document.querySelector('.close-menu').focus();else document.querySelector('.mobile-menu').focus();break;case 'clear':category='All';difficulty='All levels';query='';status='all';navigate('problems');break;case 'back':navigate('problems');break;case 'previous':openProblem(problems[problems.indexOf(activeProblem)-1]?.id);break;case 'next':openProblem(problems[problems.indexOf(activeProblem)+1]?.id);break;case 'random':{let list=filtered().filter(p=>!solved(p));if(!list.length)list=filtered();if(!list.length)list=problems;openProblem(list[Math.floor(Math.random()*list.length)].id);break}case 'hint':selectTab('hints');break;case 'reload':location.reload();break;case 'run':submit(true);break;}});
app.addEventListener('input',e=>{if(debugging.onInput?.(e)||design.onInput?.(e)||learning.onInput(e)||hdlWorkbench.onInput(e)||interview.onInput(e))return;if(simulations.onInput(e))return;account.onInput(e);admin.onInput(e);feedback.onInput(e);if(e.target.id==='search'){query=e.target.value;document.querySelector('#table-content').innerHTML=tableRows();document.querySelector('#result-count').textContent=filtered().length}if(e.target.id==='scratchpad'&&activeProblem){setPracticeField('note',activeProblem.id,e.target.value)}if(e.target.dataset.answerPart&&activeProblem)setPracticeField('draft',activeProblem.id,readAnswer());if(['answer','hdl'].includes(e.target.id)&&activeProblem){setPracticeField('draft',activeProblem.id,e.target.value)}});
app.addEventListener('change',e=>{if(debugging.onChange?.(e)||design.onChange?.(e)||interview.onChange(e))return;if(simulations.onChange(e))return;admin.onChange(e);feedback.onChange(e);if(e.target.id==='difficulty'){difficulty=e.target.value;render()}if(e.target.id==='sort'){sort=e.target.value;render()}if(e.target.name==='choice'&&activeProblem){setPracticeField('draft',activeProblem.id,e.target.value)}});
app.addEventListener('submit',e=>{if(debugging.onSubmit?.(e)||design.onSubmit?.(e)||learning.onSubmit(e)||interview.onSubmit(e))return;if(account.onSubmit(e)||feedback.onSubmit(e)||admin.onSubmit(e))return;if(e.target.id==='answer-form'){e.preventDefault();submit()}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){const search=document.querySelector('#search');if(search){e.preventDefault();search.focus()}}if(e.key==='Escape'&&menu){menu=false;document.querySelector('.sidebar').classList.remove('open');document.querySelector('.sidebar').inert=window.matchMedia('(max-width:700px)').matches;document.querySelector('.mobile-menu').focus()}});
function readRoute(){tabRequest++;const route=location.hash.slice(1)||(ownerMode?'admin':'problems');if(route!=='lab')simulations.stop();if(route!=='hdl')hdlWorkbench.stop();if(view==='reports'&&route!=='reports'&&!feedback.canLeave()){history.replaceState(null,'','#reports');return;}if(view==='admin'&&route!=='admin'&&!admin.canLeave()){history.replaceState(null,'','#admin');return;}const feedbackRoute=/^feedback\/(new|[1-9]\d*)$/.exec(route);if(feedbackRoute){const p=feedbackRoute[1]==='new'?null:problems.find(p=>p.id===Number(feedbackRoute[1]));view='problems';activeProblem=p||null;tab='description';result=null;render();if(feedbackRoute[1]==='new'||p)feedback.open(p);else toast('This problem is no longer available. Browse the current library to report an issue.');return;}if(route.startsWith('problem/')){const id=Number(route.split('/')[1]);const p=problems.find(p=>p.id===id);if(p&&activeProblem?.id!==id){activeProblem=p;tab='description';result=null;render()}}else if(['problems','saved','lab','progress','admin','reports','account','roadmap','review','interview','insights','learn','hdl','help','roles','debug','design'].includes(route)){activeProblem=null;view=route;render()}}
window.addEventListener('hashchange',readRoute);uiReady=true;render();readRoute();
window.addEventListener('pageshow',event=>{if(event.persisted)location.reload();});
window.addEventListener('focus',async()=>{if(!session.signedIn||learner.status.authLost)return;try{const current=await api('/api/session');if(session.isOwner&&!current.isOwner){session={...session,isOwner:false,ownerSignedIn:current.ownerSignedIn};render();}if(!current.signedIn||current.user?.id!==session.user?.id){await learner.refresh();return;}if(['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;await learner.refresh();if(view!=='admin'&&view!=='reports')render();}catch{if(learner.status.authLost)render();}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const defs=[{name:'list_practice_problems',title:'List Ohm practice problems',description:'Read the available electrical engineering problems and their saved completion status.',inputSchema:{type:'object',properties:{category:{type:'string',enum:categories.map(c=>c.name)}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input.category&&!categories.some(c=>c.name===input.category))throw new Error('Unknown category');return problems.filter(p=>!input.category||p.category===input.category).map(p=>({id:p.id,title:p.title,category:p.category,difficulty:p.difficulty,solved:solved(p)}))}},{name:'open_practice_problem',title:'Open an Ohm problem',description:'Navigate to a practice problem without submitting an answer or changing progress.',inputSchema:{type:'object',properties:{id:{type:'integer',minimum:1}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!Number.isInteger(input.id)||!problems.some(p=>p.id===input.id))throw new Error('Invalid problem ID');if(!openProblem(input.id))throw new Error('Navigation canceled or a save is in progress');return {id:activeProblem.id,title:activeProblem.title,prompt:activeProblem.prompt,task:activeProblem.task}}}];for(const tool of defs){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

window.matchMedia("(max-width:700px)").addEventListener("change",()=>{const sidebar=document.querySelector(".sidebar");if(sidebar)sidebar.inert=window.matchMedia("(max-width:700px)").matches&&!menu;});

window.addEventListener('storage',event=>{if(event.key===auth?.providerKey&&session.signedIn){learner.invalidateAuth();interviewStore.invalidateAuth();labStores.forEach(store=>store.invalidateAuth());render();return;}if(!isGuestStorageKey(event.key))return;try{guest=guestStore.refresh();if(!session.signedIn){saved={...guest,theme:saved.theme};if(!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&view!=='admin'&&view!=='reports')render();}}catch{toast('Browser progress could not be refreshed.');}});

window.addEventListener('beforeunload',event=>{if(labStores.some(store=>store.hasPending)||interview.hasPending()||(!session.signedIn&&guestStore.hasPending)){event.preventDefault();event.returnValue='';}});

// Keep the shared UTC daily challenge current in tabs left open overnight.
let practiceDay=utcDate();
setInterval(()=>{const today=utcDate();if(today===practiceDay)return;practiceDay=today;if(!activeProblem&&['problems','saved','roadmap','review'].includes(view)&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))render();},60000);
